DROP TABLE IF EXISTS `competitor_rankings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `competitor_rankings` (
  `rank_id` int NOT NULL AUTO_INCREMENT,
  `rank` int NOT NULL,
  `movement` int NOT NULL,
  `points` int NOT NULL,
  `competitions_played` int NOT NULL,
  `competitor_id` varchar(50) NOT NULL,
  `rank_type` varchar(20) NOT NULL DEFAULT 'doubles',
  `gender` varchar(10) NOT NULL,
  `year` int NOT NULL,
  `week` int NOT NULL,
  PRIMARY KEY (`rank_id`),
  UNIQUE KEY `uq_competitor_week` (`competitor_id`,`gender`,`year`,`week`),
  KEY `idx_rankings_competitor` (`competitor_id`),
  KEY `idx_rankings_week` (`year`,`week`),
  CONSTRAINT `fk_ranking_competitor` FOREIGN KEY (`competitor_id`) REFERENCES `competitors` (`competitor_id`)
) ENGINE=InnoDB AUTO_INCREMENT=501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

